-- =============================================================================
-- Migration 0036: K.1 Theorie B — Toepassingen van de substitutiemethode
-- =============================================================================
-- Gegenereerd door scripts/k1b-content.ts — niet met de hand bewerken.
--
-- Theorieblok B van K.1: de substitutiemethode toepassen waar de kern niet
-- meteen zichtbaar is. Tangens wordt sin/cos, een oneven macht van sinus of
-- cosinus wordt herschreven met sin² + cos² = 1, en bij een wortel maak je de
-- wortel zelf tot nieuwe variabele g. Bij een bepaalde integraal gaan de
-- grenzen mee naar g.
--
-- Eigen oefenvragen, geen boekopgaven. Elke primitieve wordt nagerekend door
-- src/content/primitieven.test.ts (content/hoofdstuk-k/k1b.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 6 clusters
--   • 36 vragen met elk 4 stappen (144 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k1b_gonio', $ksql$Gonio primitiveren met de substitutiemethode$ksql$, 7, 'primitiveren'),
  ('k1b_bepaald', $ksql$Bepaalde integralen met de substitutiemethode$ksql$, 8, 'integralen'),
  ('k1b_toepassingen', $ksql$Oppervlakte met de substitutiemethode$ksql$, 9, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k1b_gonio', 'k1b_tangens', $ksql$Tangens en breuken met sinus en cosinus$ksql$, 1),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Oneven machten van sinus en cosinus$ksql$, 2),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Grenzen omzetten bij gonio$ksql$, 1),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Grenzen omzetten bij ln en e$ksql$, 2),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$De substitutie wortel(x + a) = g$ksql$, 3),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Oppervlakte en p bepalen$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

