  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \sin(x) + \dfrac{\sin(x)}{\cos^{2}(x)}$$ksql$, $ksql$-cos(x) + 1/cos(x) + c$ksql$, $ksql$F(x) = -\cos(x) + \dfrac{1}{\cos(x)} + c$ksql$, 3, 5, ARRAY[$ksql$1/cos(x) - cos(x) + c$ksql$, $ksql$-cos(x) + cos(x)^(-1) + c$ksql$]::text[]),
