  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin(x)\cos^{2}(x)$$ksql$, $ksql$-cos(x)^3/3 + c$ksql$, $ksql$F(x) = -\tfrac{1}{3}\cos^{3}(x) + c$ksql$, 1, 1, ARRAY[$ksql$-1/3 cos(x)^3 + c$ksql$, $ksql$-(1/3)cos(x)^3 + c$ksql$]::text[]),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(x)$$ksql$, $ksql$sin(x) - sin(x)^3/3 + c$ksql$, $ksql$F(x) = \sin(x) - \tfrac{1}{3}\sin^{3}(x) + c$ksql$, 1, 2, ARRAY[$ksql$sin(x) - 1/3 sin(x)^3 + c$ksql$]::text[]),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(2x)$$ksql$, $ksql$-cos(2x)/2 + cos(2x)^3/6 + c$ksql$, $ksql$F(x) = -\tfrac{1}{2}\cos(2x) + \tfrac{1}{6}\cos^{3}(2x) + c$ksql$, 2, 3, ARRAY[$ksql$-1/2 cos(2x) + 1/6 cos(2x)^3 + c$ksql$, $ksql$cos(2x)^3/6 - cos(2x)/2 + c$ksql$]::text[]),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{5}(x)$$ksql$, $ksql$sin(x) - 2/3 sin(x)^3 + 1/5 sin(x)^5 + c$ksql$, $ksql$F(x) = \sin(x) - \tfrac{2}{3}\sin^{3}(x) + \tfrac{1}{5}\sin^{5}(x) + c$ksql$, 2, 4, ARRAY[$ksql$sin(x) - 2sin(x)^3/3 + sin(x)^5/5 + c$ksql$]::text[]),
