  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $h(x) = \dfrac{\cos^{3}(x)}{\sin^{2}(x)}$$ksql$, $ksql$-1/sin(x) - sin(x) + c$ksql$, $ksql$H(x) = -\dfrac{1}{\sin(x)} - \sin(x) + c$ksql$, 3, 6, ARRAY[$ksql$-sin(x) - 1/sin(x) + c$ksql$, $ksql$-sin(x)^(-1) - sin(x) + c$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{8}\pi} \tan(2x)\,\mathrm{d}x$$ksql$, $ksql$ln(2)/4$ksql$, $ksql$\tfrac{1}{4}\ln(2)$ksql$, 1, 1, ARRAY[$ksql$1/4 ln(2)$ksql$, $ksql$0,25ln(2)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\sin(x)}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, $ksql$sqrt(2) - 1$ksql$, $ksql$\sqrt{2} - 1$ksql$, 1, 2, ARRAY[$ksql$-1 + sqrt(2)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \sin^{3}(x)\,\mathrm{d}x$$ksql$, $ksql$2/3$ksql$, $ksql$\tfrac{2}{3}$ksql$, 2, 3, ARRAY[]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} \cos^{3}(x)\,\mathrm{d}x$$ksql$, $ksql$3/8 sqrt(3)$ksql$, $ksql$\tfrac{3}{8}\sqrt{3}$ksql$, 2, 4, ARRAY[$ksql$3sqrt(3)/8$ksql$, $ksql$0,375sqrt(3)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{\sin^{3}(x)}\,\mathrm{d}x$$ksql$, $ksql$3/2$ksql$, $ksql$\tfrac{3}{2}$ksql$, 3, 5, ARRAY[$ksql$1,5$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\cos(x)}{3 + \sin(x)}\,\mathrm{d}x$$ksql$, $ksql$ln((6 + sqrt(2))/6)$ksql$, $ksql$\ln\left(\dfrac{6 + \sqrt{2}}{6}\right)$ksql$, 3, 6, ARRAY[$ksql$ln(3 + 1/2 sqrt(2)) - ln(3)$ksql$, $ksql$ln(1 + sqrt(2)/6)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \dfrac{\ln(x)}{x}\,\mathrm{d}x$$ksql$, $ksql$1/2$ksql$, $ksql$\tfrac{1}{2}$ksql$, 1, 1, ARRAY[$ksql$0,5$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\,\mathrm{e}^{x^{2}}\,\mathrm{d}x$$ksql$, $ksql$(e - 1)/2$ksql$, $ksql$\tfrac{1}{2}\left(\mathrm{e} - 1\right)$ksql$, 1, 2, ARRAY[$ksql$1/2 e - 1/2$ksql$, $ksql$1/2(e - 1)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}^{3}} \dfrac{\ln^{2}(x)}{x}\,\mathrm{d}x$$ksql$, $ksql$9$ksql$, $ksql$9$ksql$, 2, 3, ARRAY[]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{4}} \dfrac{1}{x\ln(x)}\,\mathrm{d}x$$ksql$, $ksql$ln(4)$ksql$, $ksql$\ln(4)$ksql$, 2, 4, ARRAY[$ksql$2ln(2)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{x^{2}}{\mathrm{e}^{x^{3}}}\,\mathrm{d}x$$ksql$, $ksql$(e - 1)/(3e)$ksql$, $ksql$\dfrac{\mathrm{e} - 1}{3\mathrm{e}}$ksql$, 3, 5, ARRAY[$ksql$1/3 - 1/(3e)$ksql$, $ksql$(1 - e^(-1))/3$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{1}{x\sqrt{\ln(x)}}\,\mathrm{d}x$$ksql$, $ksql$2sqrt(2) - 2$ksql$, $ksql$2\sqrt{2} - 2$ksql$, 3, 6, ARRAY[$ksql$2(sqrt(2) - 1)$ksql$, $ksql$-2 + 2sqrt(2)$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{12} \dfrac{x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, $ksql$64/3$ksql$, $ksql$\tfrac{64}{3}$ksql$, 1, 1, ARRAY[$ksql$21 1/3$ksql$, $ksql$21⅓$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 3} = g$: $\displaystyle\int_{1}^{6} x\sqrt{x + 3}\,\mathrm{d}x$$ksql$, $ksql$232/5$ksql$, $ksql$\tfrac{232}{5}$ksql$, 1, 2, ARRAY[$ksql$46 2/5$ksql$, $ksql$46,4$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x - 1} = g$: $\displaystyle\int_{1}^{10} x\sqrt{x - 1}\,\mathrm{d}x$$ksql$, $ksql$576/5$ksql$, $ksql$\tfrac{576}{5}$ksql$, 2, 3, ARRAY[$ksql$115 1/5$ksql$, $ksql$115,2$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{5} \dfrac{6x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, $ksql$28$ksql$, $ksql$28$ksql$, 2, 4, ARRAY[]::text[]),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 1} = g$: $\displaystyle\int_{0}^{4} \dfrac{x}{\sqrt{2x + 1}}\,\mathrm{d}x$$ksql$, $ksql$10/3$ksql$, $ksql$\tfrac{10}{3}$ksql$, 3, 5, ARRAY[$ksql$3 1/3$ksql$, $ksql$3⅓$ksql$]::text[]),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 3} = g$: $\displaystyle\int_{-1}^{3} x\sqrt{2x + 3}\,\mathrm{d}x$$ksql$, $ksql$56/5$ksql$, $ksql$\tfrac{56}{5}$ksql$, 3, 6, ARRAY[$ksql$11 1/5$ksql$, $ksql$11,2$ksql$]::text[]),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}^{2}$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$2$ksql$, $ksql$2$ksql$, 1, 1, ARRAY[]::text[]),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sin(x)\cos^{2}(x)$, de $x$-as en de lijn $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$1/3$ksql$, $ksql$\tfrac{1}{3}$ksql$, 1, 2, ARRAY[]::text[]),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \tan(x)$, de $x$-as en de lijn $x = \tfrac{1}{3}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$ln(2)$ksql$, $ksql$\ln(2)$ksql$, 2, 3, ARRAY[]::text[]),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{3x^{2}}{x^{3} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(9)$. Bereken exact $p$.$ksql$, $ksql$2$ksql$, $ksql$p = 2$ksql$, 2, 4, ARRAY[$ksql$p = 2$ksql$]::text[]),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Gegeven zijn de functies $f(x) = \dfrac{9\ln^{2}(x)}{x}$ en $h(x) = \dfrac{1}{x}$. Bereken exact de oppervlakte van het vlakdeel $V$ dat wordt ingesloten door de grafieken van $f$ en $h$.$ksql$, $ksql$4/9$ksql$, $ksql$\tfrac{4}{9}$ksql$, 3, 5, ARRAY[]::text[]),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(3)$. Bereken exact $p$.$ksql$, $ksql$2sqrt(2)$ksql$, $ksql$p = 2\sqrt{2}$ksql$, 3, 6, ARRAY[$ksql$p = 2sqrt(2)$ksql$, $ksql$sqrt(8)$ksql$, $ksql$p = sqrt(8)$ksql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(4x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een tangens, of een breuk met een sinus en een cosinus → substitutiemethode. Schrijf $\tan = \dfrac{\sin}{\cos}$ en kijk welke van de twee de kern is: de ándere staat er dan als afgeleide bij.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(4x)$$ksql$, 1, $ksql$Herschrijf: $\tan(4x) = \dfrac{\sin(4x)}{\cos(4x)}$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(4x)$$ksql$, 2, $ksql$Kies de kern: $g(x) = \cos(4x)$, dus $g'(x) = -4\sin(4x)$. Dat betekent $\sin(4x)\,\mathrm{d}x = -\tfrac{1}{4}\,\mathrm{d}(\cos(4x))$, dus $\int \tan(4x)\,\mathrm{d}x = \int -\tfrac{1}{4} \cdot \dfrac{1}{g}\,\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(4x)$$ksql$, 3, $ksql$Primitiveer: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$, dus $F(x) = -\tfrac{1}{4}\ln|\cos(4x)| + c$. Controle: differentiëren geeft $-\tfrac{1}{4} \cdot \dfrac{-4\sin(4x)}{\cos(4x)} = \tan(4x)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan\left(\tfrac{1}{2}x\right)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een tangens, of een breuk met een sinus en een cosinus → substitutiemethode. Schrijf $\tan = \dfrac{\sin}{\cos}$ en kijk welke van de twee de kern is: de ándere staat er dan als afgeleide bij.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan\left(\tfrac{1}{2}x\right)$$ksql$, 1, $ksql$Herschrijf: $\tan\left(\tfrac{1}{2}x\right) = \dfrac{\sin\left(\tfrac{1}{2}x\right)}{\cos\left(\tfrac{1}{2}x\right)}$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan\left(\tfrac{1}{2}x\right)$$ksql$, 2, $ksql$Kies de kern: $g(x) = \cos\left(\tfrac{1}{2}x\right)$, dus $g'(x) = -\tfrac{1}{2}\sin\left(\tfrac{1}{2}x\right)$. Dat betekent $\sin\left(\tfrac{1}{2}x\right)\mathrm{d}x = -2\,\mathrm{d}\left(\cos\left(\tfrac{1}{2}x\right)\right)$, dus de integraal wordt $\int -2 \cdot \dfrac{1}{g}\,\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan\left(\tfrac{1}{2}x\right)$$ksql$, 3, $ksql$Primitiveer: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$, dus $F(x) = -2\ln\left|\cos\left(\tfrac{1}{2}x\right)\right| + c$. Controle: differentiëren geeft $-2 \cdot \dfrac{-\tfrac{1}{2}\sin\left(\tfrac{1}{2}x\right)}{\cos\left(\tfrac{1}{2}x\right)} = \tan\left(\tfrac{1}{2}x\right)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\sin(x)}{\cos^{4}(x)}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een sinus en een cosinus → substitutiemethode. De ene gonio is de kern, de andere is (op een teken na) zijn afgeleide.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\sin(x)}{\cos^{4}(x)}$$ksql$, 1, $ksql$Herschrijf de noemer als macht: $f(x) = \sin(x) \cdot \cos^{-4}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\sin(x)}{\cos^{4}(x)}$$ksql$, 2, $ksql$Kies de kern: $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$. Dat betekent $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$, dus de integraal wordt $\int -g^{-4}\,\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\sin(x)}{\cos^{4}(x)}$$ksql$, 3, $ksql$Primitiveer: $\int -g^{-4}\,\mathrm{d}g = \tfrac{1}{3}g^{-3}$, dus $F(x) = \dfrac{1}{3\cos^{3}(x)} + c$. Controle: differentiëren geeft $\tfrac{1}{3} \cdot -3\cos^{-4}(x) \cdot -\sin(x) = \dfrac{\sin(x)}{\cos^{4}(x)}$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $h(x) = \dfrac{\cos(x)}{\sin^{3}(x)}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een sinus en een cosinus → substitutiemethode. De ene gonio is de kern, de andere is (op een teken na) zijn afgeleide.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $h(x) = \dfrac{\cos(x)}{\sin^{3}(x)}$$ksql$, 1, $ksql$Herschrijf de noemer als macht: $h(x) = \cos(x) \cdot \sin^{-3}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $h(x) = \dfrac{\cos(x)}{\sin^{3}(x)}$$ksql$, 2, $ksql$Nu is de sinus de kern: $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. Dat betekent $\cos(x)\,\mathrm{d}x = \mathrm{d}(\sin(x))$, dus de integraal wordt $\int g^{-3}\,\mathrm{d}g$ — hier zonder minteken.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $h(x) = \dfrac{\cos(x)}{\sin^{3}(x)}$$ksql$, 3, $ksql$Primitiveer: $\int g^{-3}\,\mathrm{d}g = -\tfrac{1}{2}g^{-2}$, dus $H(x) = -\dfrac{1}{2\sin^{2}(x)} + c$. Controle: differentiëren geeft $-\tfrac{1}{2} \cdot -2\sin^{-3}(x) \cdot \cos(x) = \dfrac{\cos(x)}{\sin^{3}(x)}$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \sin(x) + \dfrac{\sin(x)}{\cos^{2}(x)}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een $+$ tussen twee delen → somregel, dus elk deel apart primitiveren. Het tweede deel is een breuk met een sinus en een cosinus → substitutiemethode.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \sin(x) + \dfrac{\sin(x)}{\cos^{2}(x)}$$ksql$, 1, $ksql$Het eerste deel is een standaardprimitieve: $\int \sin(x)\,\mathrm{d}x = -\cos(x)$. Het tweede deel schrijf je als $\sin(x) \cdot \cos^{-2}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \sin(x) + \dfrac{\sin(x)}{\cos^{2}(x)}$$ksql$, 2, $ksql$Kies voor dat tweede deel de kern: $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$. Dat betekent $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$, dus dat deel wordt $\int -g^{-2}\,\mathrm{d}g = g^{-1}$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \sin(x) + \dfrac{\sin(x)}{\cos^{2}(x)}$$ksql$, 3, $ksql$Tel op: $F(x) = -\cos(x) + \dfrac{1}{\cos(x)} + c$. Controle: differentiëren geeft $\sin(x) + \left(-\cos^{-2}(x) \cdot -\sin(x)\right) = \sin(x) + \dfrac{\sin(x)}{\cos^{2}(x)}$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{2 + \sin(x)}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een hele uitdrukking in de noemer → kijk of de teller de afgeleide van die noemer is. Zo ja, dan komt er $\ln$ uit.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{2 + \sin(x)}$$ksql$, 1, $ksql$De noemer is niet zomaar een sinus of cosinus, maar $2 + \sin(x)$. Juist dát hele stuk is de kern.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{2 + \sin(x)}$$ksql$, 2, $ksql$Kies de kern: $g(x) = 2 + \sin(x)$, dus $g'(x) = \cos(x)$. De teller is precies $g'(x)$, dus $\cos(x)\,\mathrm{d}x = \mathrm{d}(2 + \sin(x))$ en de integraal wordt $\int \dfrac{1}{g}\,\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{2 + \sin(x)}$$ksql$, 3, $ksql$Primitiveer: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$, dus $F(x) = \ln(2 + \sin(x)) + c$; omdat $\sin(x)$ nooit onder $-1$ komt, is $2 + \sin(x)$ altijd positief en mogen de strepen weg. Controle: differentiëren geeft $\dfrac{\cos(x)}{2 + \sin(x)}$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin(x)\cos^{2}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een cosinus met een losse sinus ernaast. Die losse sinus is (op een minteken na) de afgeleide van de cosinus → substitutiemethode. Hier hoeft er nog niets herschreven te worden.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin(x)\cos^{2}(x)$$ksql$, 1, $ksql$Er staat al $\cos^{2}(x) \cdot \sin(x)$: een macht van de kern, met de afgeleide van de kern ernaast.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin(x)\cos^{2}(x)$$ksql$, 2, $ksql$Kies de kern: $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$. Dat betekent $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$, dus de integraal wordt $\int -g^{2}\,\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin(x)\cos^{2}(x)$$ksql$, 3, $ksql$Primitiveer: $\int -g^{2}\,\mathrm{d}g = -\tfrac{1}{3}g^{3}$, dus $F(x) = -\tfrac{1}{3}\cos^{3}(x) + c$. Controle: differentiëren geeft $-\tfrac{1}{3} \cdot 3\cos^{2}(x) \cdot -\sin(x) = \sin(x)\cos^{2}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een oneven macht van een sinus of cosinus → splits er één factor af en herschrijf de rest met $\sin^{2} + \cos^{2} = 1$. Die ene losse factor is precies de afgeleide die je nodig hebt.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(x)$$ksql$, 1, $ksql$Splits één cosinus af en herschrijf de rest: $\cos^{3}(x) = \cos^{2}(x) \cdot \cos(x) = \left(1 - \sin^{2}(x)\right)\cos(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(x)$$ksql$, 2, $ksql$Nu is de sinus de kern: $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. De losse cosinus is precies $g'(x)$: $\cos(x)\,\mathrm{d}x = \mathrm{d}(\sin(x))$, dus de integraal wordt $\int \left(1 - g^{2}\right)\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(x)$$ksql$, 3, $ksql$Primitiveer term voor term: $\int \left(1 - g^{2}\right)\mathrm{d}g = g - \tfrac{1}{3}g^{3}$, dus $F(x) = \sin(x) - \tfrac{1}{3}\sin^{3}(x) + c$. Controle: differentiëren geeft $\cos(x) - \sin^{2}(x)\cos(x) = \cos(x)\left(1 - \sin^{2}(x)\right) = \cos^{3}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een oneven macht van een sinus of cosinus → splits er één factor af en herschrijf de rest met $\sin^{2} + \cos^{2} = 1$. Die ene losse factor is precies de afgeleide die je nodig hebt.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(2x)$$ksql$, 1, $ksql$Splits één sinus af en herschrijf de rest: $\sin^{3}(2x) = \left(1 - \cos^{2}(2x)\right)\sin(2x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(2x)$$ksql$, 2, $ksql$Kies de kern: $g(x) = \cos(2x)$, dus $g'(x) = -2\sin(2x)$. Dat betekent $\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}\,\mathrm{d}(\cos(2x))$, dus de integraal wordt $\int -\tfrac{1}{2}\left(1 - g^{2}\right)\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(2x)$$ksql$, 3, $ksql$Primitiveer: $-\tfrac{1}{2}\left(g - \tfrac{1}{3}g^{3}\right) = -\tfrac{1}{2}g + \tfrac{1}{6}g^{3}$, dus $F(x) = -\tfrac{1}{2}\cos(2x) + \tfrac{1}{6}\cos^{3}(2x) + c$. Controle: differentiëren geeft $\sin(2x) - \cos^{2}(2x)\sin(2x) = \sin^{3}(2x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{5}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een oneven macht van een sinus of cosinus → splits er één factor af en herschrijf de rest met $\sin^{2} + \cos^{2} = 1$. Die ene losse factor is precies de afgeleide die je nodig hebt.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{5}(x)$$ksql$, 1, $ksql$Splits één cosinus af: $\cos^{5}(x) = \left(\cos^{2}(x)\right)^{2}\cos(x) = \left(1 - \sin^{2}(x)\right)^{2}\cos(x)$. Werk het kwadraat uit: $\left(1 - 2\sin^{2}(x) + \sin^{4}(x)\right)\cos(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{5}(x)$$ksql$, 2, $ksql$Kies de kern: $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. De losse cosinus is precies $g'(x)$, dus de integraal wordt $\int \left(1 - 2g^{2} + g^{4}\right)\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{5}(x)$$ksql$, 3, $ksql$Primitiveer term voor term: $g - \tfrac{2}{3}g^{3} + \tfrac{1}{5}g^{5}$, dus $F(x) = \sin(x) - \tfrac{2}{3}\sin^{3}(x) + \tfrac{1}{5}\sin^{5}(x) + c$. Controle: differentiëren geeft $\cos(x)\left(1 - 2\sin^{2}(x) + \sin^{4}(x)\right) = \cos(x)\left(1 - \sin^{2}(x)\right)^{2} = \cos^{5}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)\cos^{2}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een sinus én een cosinus met machten. Omdat de macht van de sinus oneven is, splits je dáár één factor af → substitutiemethode met de cosinus als kern.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)\cos^{2}(x)$$ksql$, 1, $ksql$Splits één sinus af: $\sin^{3}(x)\cos^{2}(x) = \left(1 - \cos^{2}(x)\right)\cos^{2}(x)\sin(x) = \left(\cos^{2}(x) - \cos^{4}(x)\right)\sin(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)\cos^{2}(x)$$ksql$, 2, $ksql$Kies de kern: $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$. Dat betekent $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$, dus de integraal wordt $\int -\left(g^{2} - g^{4}\right)\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)\cos^{2}(x)$$ksql$, 3, $ksql$Primitiveer term voor term: $-\tfrac{1}{3}g^{3} + \tfrac{1}{5}g^{5}$, dus $F(x) = -\tfrac{1}{3}\cos^{3}(x) + \tfrac{1}{5}\cos^{5}(x) + c$. Controle: differentiëren geeft $\sin(x)\cos^{2}(x) - \sin(x)\cos^{4}(x) = \sin(x)\cos^{2}(x)\left(1 - \cos^{2}(x)\right) = \sin^{3}(x)\cos^{2}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $h(x) = \dfrac{\cos^{3}(x)}{\sin^{2}(x)}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een oneven macht van de cosinus boven en een macht van de sinus onder. Splits één cosinus af → substitutiemethode met de sinus als kern.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $h(x) = \dfrac{\cos^{3}(x)}{\sin^{2}(x)}$$ksql$, 1, $ksql$Splits één cosinus af: $\dfrac{\cos^{3}(x)}{\sin^{2}(x)} = \dfrac{1 - \sin^{2}(x)}{\sin^{2}(x)} \cdot \cos(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $h(x) = \dfrac{\cos^{3}(x)}{\sin^{2}(x)}$$ksql$, 2, $ksql$Kies de kern: $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. De losse cosinus is precies $g'(x)$, dus de integraal wordt $\int \dfrac{1 - g^{2}}{g^{2}}\,\mathrm{d}g = \int \left(g^{-2} - 1\right)\mathrm{d}g$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $h(x) = \dfrac{\cos^{3}(x)}{\sin^{2}(x)}$$ksql$, 3, $ksql$Primitiveer term voor term: $-g^{-1} - g$, dus $H(x) = -\dfrac{1}{\sin(x)} - \sin(x) + c$. Controle: differentiëren geeft $\dfrac{\cos(x)}{\sin^{2}(x)} - \cos(x) = \dfrac{\cos(x)\left(1 - \sin^{2}(x)\right)}{\sin^{2}(x)} = \dfrac{\cos^{3}(x)}{\sin^{2}(x)}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{8}\pi} \tan(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: gonio die je eerst herschrijft tot een kern met zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{8}\pi} \tan(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Herschrijf $\tan(2x) = \dfrac{\sin(2x)}{\cos(2x)}$ en kies de kern $g(x) = \cos(2x)$, dus $g'(x) = -2\sin(2x)$ en $\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}\,\mathrm{d}(\cos(2x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{8}\pi} \tan(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Primitiveer naar de kern: $\int -\tfrac{1}{2} \cdot \dfrac{1}{g}\,\mathrm{d}g = -\tfrac{1}{2}\ln|g|$, dus een primitieve is $-\tfrac{1}{2}\ln|\cos(2x)|$. Je kunt ook de grenzen van $g$ opschrijven: bij $x = 0$ hoort $g = 1$ en bij $x = \tfrac{1}{8}\pi$ hoort $g = \cos\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{8}\pi} \tan(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[-\tfrac{1}{2}\ln|\cos(2x)|\right]_{0}^{\frac{1}{8}\pi} = -\tfrac{1}{2}\ln\left(\tfrac{1}{2}\sqrt{2}\right) + \tfrac{1}{2}\ln(1)$. Omdat $\tfrac{1}{2}\sqrt{2} = 2^{-\frac{1}{2}}$ is dat $-\tfrac{1}{2} \cdot -\tfrac{1}{2}\ln(2) = \tfrac{1}{4}\ln(2)$. Exact laten staan.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\sin(x)}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: gonio die je eerst herschrijft tot een kern met zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\sin(x)}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Schrijf als macht: $\sin(x) \cdot \cos^{-2}(x)$. Kies de kern $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$ en $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\sin(x)}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int -g^{-2}\,\mathrm{d}g = g^{-1}$, dus een primitieve is $\dfrac{1}{\cos(x)}$. De grenzen van $g$: bij $x = 0$ hoort $g = 1$, bij $x = \tfrac{1}{4}\pi$ hoort $g = \tfrac{1}{2}\sqrt{2}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\sin(x)}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\dfrac{1}{\cos(x)}\right]_{0}^{\frac{1}{4}\pi} = \dfrac{1}{\tfrac{1}{2}\sqrt{2}} - \dfrac{1}{1} = \sqrt{2} - 1$. Exact laten staan, dus niet afronden.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \sin^{3}(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: gonio die je eerst herschrijft tot een kern met zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \sin^{3}(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Splits één sinus af: $\sin^{3}(x) = \left(1 - \cos^{2}(x)\right)\sin(x)$. Kies de kern $g(x) = \cos(x)$, dus $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \sin^{3}(x)\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int -\left(1 - g^{2}\right)\mathrm{d}g = \tfrac{1}{3}g^{3} - g$, dus een primitieve is $\tfrac{1}{3}\cos^{3}(x) - \cos(x)$. De grenzen van $g$: bij $x = 0$ hoort $g = 1$, bij $x = \tfrac{1}{2}\pi$ hoort $g = 0$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \sin^{3}(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\tfrac{1}{3}\cos^{3}(x) - \cos(x)\right]_{0}^{\frac{1}{2}\pi} = (0 - 0) - \left(\tfrac{1}{3} - 1\right) = \tfrac{2}{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} \cos^{3}(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: gonio die je eerst herschrijft tot een kern met zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} \cos^{3}(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Splits één cosinus af: $\cos^{3}(x) = \left(1 - \sin^{2}(x)\right)\cos(x)$. Kies de kern $g(x) = \sin(x)$, dus $\cos(x)\,\mathrm{d}x = \mathrm{d}(\sin(x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} \cos^{3}(x)\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int \left(1 - g^{2}\right)\mathrm{d}g = g - \tfrac{1}{3}g^{3}$, dus een primitieve is $\sin(x) - \tfrac{1}{3}\sin^{3}(x)$. De grenzen van $g$: bij $x = 0$ hoort $g = 0$, bij $x = \tfrac{1}{3}\pi$ hoort $g = \tfrac{1}{2}\sqrt{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} \cos^{3}(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[g - \tfrac{1}{3}g^{3}\right]_{0}^{\frac{1}{2}\sqrt{3}} = \tfrac{1}{2}\sqrt{3} - \tfrac{1}{3} \cdot \tfrac{3}{8}\sqrt{3} = \tfrac{1}{2}\sqrt{3} - \tfrac{1}{8}\sqrt{3} = \tfrac{3}{8}\sqrt{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{\sin^{3}(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: gonio die je eerst herschrijft tot een kern met zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{\sin^{3}(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Schrijf als macht: $\cos(x) \cdot \sin^{-3}(x)$. Kies de kern $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$ en $\cos(x)\,\mathrm{d}x = \mathrm{d}(\sin(x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{\sin^{3}(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int g^{-3}\,\mathrm{d}g = -\tfrac{1}{2}g^{-2}$. De grenzen van $g$: bij $x = \tfrac{1}{6}\pi$ hoort $g = \tfrac{1}{2}$, bij $x = \tfrac{1}{2}\pi$ hoort $g = 1$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{\sin^{3}(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[-\dfrac{1}{2g^{2}}\right]_{\frac{1}{2}}^{1} = -\tfrac{1}{2} - \left(-\dfrac{1}{2 \cdot \tfrac{1}{4}}\right) = -\tfrac{1}{2} + 2 = 1\tfrac{1}{2}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\cos(x)}{3 + \sin(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een breuk met een hele uitdrukking in de noemer en de afgeleide daarvan in de teller → er komt $\ln$ uit.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\cos(x)}{3 + \sin(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies de kern: $g(x) = 3 + \sin(x)$, dus $g'(x) = \cos(x)$. De teller is precies $g'(x)$, dus $\cos(x)\,\mathrm{d}x = \mathrm{d}(3 + \sin(x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\cos(x)}{3 + \sin(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$. De grenzen van $g$: bij $x = 0$ hoort $g = 3$, bij $x = \tfrac{1}{4}\pi$ hoort $g = 3 + \tfrac{1}{2}\sqrt{2}$. Beide zijn positief, dus de strepen mogen weg.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{\cos(x)}{3 + \sin(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\ln(g)\right]_{3}^{3 + \frac{1}{2}\sqrt{2}} = \ln\left(3 + \tfrac{1}{2}\sqrt{2}\right) - \ln(3) = \ln\left(\dfrac{6 + \sqrt{2}}{6}\right)$. Exact laten staan.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \dfrac{\ln(x)}{x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een $\ln$ of een e-macht met een kern erin → substitutiemethode.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \dfrac{\ln(x)}{x}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies de kern: $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$. Die $\dfrac{1}{x}$ staat er als factor bij: $\dfrac{\ln(x)}{x} = \ln(x) \cdot \dfrac{1}{x}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \dfrac{\ln(x)}{x}\,\mathrm{d}x$$ksql$, 2, $ksql$Dan is $\dfrac{1}{x}\,\mathrm{d}x = \mathrm{d}(\ln(x))$ en wordt de integraal $\int g\,\mathrm{d}g = \tfrac{1}{2}g^{2}$. De grenzen van $g$: bij $x = 1$ hoort $g = 0$, bij $x = \mathrm{e}$ hoort $g = 1$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \dfrac{\ln(x)}{x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\tfrac{1}{2}g^{2}\right]_{0}^{1} = \tfrac{1}{2} - 0 = \tfrac{1}{2}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\,\mathrm{e}^{x^{2}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een $\ln$ of een e-macht met een kern erin → substitutiemethode.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\,\mathrm{e}^{x^{2}}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2}$, dus $g'(x) = 2x$. Vóór de e-macht staat $x = \tfrac{1}{2}g'(x)$: dat past op een constante na.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\,\mathrm{e}^{x^{2}}\,\mathrm{d}x$$ksql$, 2, $ksql$Dan is $x\,\mathrm{d}x = \tfrac{1}{2}\,\mathrm{d}\left(x^{2}\right)$ en wordt de integraal $\int \tfrac{1}{2}\mathrm{e}^{g}\,\mathrm{d}g = \tfrac{1}{2}\mathrm{e}^{g}$. De grenzen van $g$: bij $x = 0$ hoort $g = 0$, bij $x = 1$ hoort $g = 1$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\,\mathrm{e}^{x^{2}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\tfrac{1}{2}\mathrm{e}^{g}\right]_{0}^{1} = \tfrac{1}{2}\mathrm{e} - \tfrac{1}{2} = \tfrac{1}{2}\left(\mathrm{e} - 1\right)$. Exact laten staan.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}^{3}} \dfrac{\ln^{2}(x)}{x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een $\ln$ of een e-macht met een kern erin → substitutiemethode.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}^{3}} \dfrac{\ln^{2}(x)}{x}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies de kern: $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$. Er staat $\ln^{2}(x) \cdot \dfrac{1}{x}$: een macht van de kern met zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}^{3}} \dfrac{\ln^{2}(x)}{x}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int g^{2}\,\mathrm{d}g = \tfrac{1}{3}g^{3}$. De grenzen van $g$: bij $x = 1$ hoort $g = \ln(1) = 0$, bij $x = \mathrm{e}^{3}$ hoort $g = \ln\left(\mathrm{e}^{3}\right) = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}^{3}} \dfrac{\ln^{2}(x)}{x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\tfrac{1}{3}g^{3}\right]_{0}^{3} = \tfrac{1}{3} \cdot 27 - 0 = 9$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{4}} \dfrac{1}{x\ln(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een $\ln$ of een e-macht met een kern erin → substitutiemethode.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{4}} \dfrac{1}{x\ln(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies de kern: $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$. Herschrijf de breuk als $\dfrac{1}{\ln(x)} \cdot \dfrac{1}{x}$: de kern staat in de noemer, zijn afgeleide ernaast.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{4}} \dfrac{1}{x\ln(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$. De grenzen van $g$: bij $x = \mathrm{e}$ hoort $g = 1$, bij $x = \mathrm{e}^{4}$ hoort $g = 4$. Allebei positief, dus de strepen mogen weg.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{4}} \dfrac{1}{x\ln(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[\ln(g)\right]_{1}^{4} = \ln(4) - \ln(1) = \ln(4)$. Exact laten staan.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{x^{2}}{\mathrm{e}^{x^{3}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een $\ln$ of een e-macht met een kern erin → substitutiemethode.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{x^{2}}{\mathrm{e}^{x^{3}}}\,\mathrm{d}x$$ksql$, 1, $ksql$Haal de e-macht eerst naar boven: $\dfrac{x^{2}}{\mathrm{e}^{x^{3}}} = x^{2}\mathrm{e}^{-x^{3}}$. Kies de kern $g(x) = -x^{3}$, dus $g'(x) = -3x^{2}$ en $x^{2}\,\mathrm{d}x = -\tfrac{1}{3}\,\mathrm{d}\left(-x^{3}\right)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{x^{2}}{\mathrm{e}^{x^{3}}}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int -\tfrac{1}{3}\mathrm{e}^{g}\,\mathrm{d}g = -\tfrac{1}{3}\mathrm{e}^{g}$. De grenzen van $g$: bij $x = 0$ hoort $g = 0$, bij $x = 1$ hoort $g = -1$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{x^{2}}{\mathrm{e}^{x^{3}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[-\tfrac{1}{3}\mathrm{e}^{g}\right]_{0}^{-1} = -\tfrac{1}{3}\mathrm{e}^{-1} + \tfrac{1}{3} = \dfrac{\mathrm{e} - 1}{3\mathrm{e}}$. Exact laten staan.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{1}{x\sqrt{\ln(x)}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus na het primitiveren komen de grenzen aan de beurt. Buitenste schil: een $\ln$ of een e-macht met een kern erin → substitutiemethode.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{1}{x\sqrt{\ln(x)}}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies de kern: $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$. Herschrijf als $\dfrac{1}{\sqrt{\ln(x)}} \cdot \dfrac{1}{x}$, en de wortel als macht: $g^{-\frac{1}{2}}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{1}{x\sqrt{\ln(x)}}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int g^{-\frac{1}{2}}\,\mathrm{d}g = 2g^{\frac{1}{2}} = 2\sqrt{g}$. De grenzen van $g$: bij $x = \mathrm{e}$ hoort $g = 1$, bij $x = \mathrm{e}^{2}$ hoort $g = 2$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{1}{x\sqrt{\ln(x)}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul in: $\left[2\sqrt{g}\right]_{1}^{2} = 2\sqrt{2} - 2$. Exact laten staan.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{12} \dfrac{x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus (of min) een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt hier niet. Stel daarom de hele wortel gelijk aan een nieuwe variabele $g$. Hier is dat $g = \sqrt{x + 4}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{12} \dfrac{x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadrateren geeft $g^{2} = x + 4$, dus $x = g^{2} - 4$ en $\mathrm{d}x = \mathrm{d}\left(g^{2} - 4\right) = 2g\,\mathrm{d}g$. De grenzen gaan mee: bij $x = 0$ hoort $g = \sqrt{4} = 2$ en bij $x = 12$ hoort $g = \sqrt{16} = 4$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{12} \dfrac{x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 2, $ksql$Zet alles om: $\displaystyle\int_{0}^{12} \dfrac{x}{\sqrt{x + 4}}\,\mathrm{d}x = \int_{2}^{4} \dfrac{g^{2} - 4}{g} \cdot 2g\,\mathrm{d}g = \int_{2}^{4} \left(2g^{2} - 8\right)\mathrm{d}g$. Er staat geen $x$ meer in: dat is het teken dat de substitutie klopt.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{12} \dfrac{x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 3, $ksql$Primitiveer en vul de grenzen in: $\left[\tfrac{2}{3}g^{3} - 8g\right]_{2}^{4} = \left(\tfrac{128}{3} - 32\right) - \left(\tfrac{16}{3} - 16\right) = \tfrac{112}{3} - 16 = \tfrac{64}{3}$. De uitkomst is $21\tfrac{1}{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 3} = g$: $\displaystyle\int_{1}^{6} x\sqrt{x + 3}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus (of min) een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt hier niet. Stel daarom de hele wortel gelijk aan een nieuwe variabele $g$. Hier is dat $g = \sqrt{x + 3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 3} = g$: $\displaystyle\int_{1}^{6} x\sqrt{x + 3}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadrateren geeft $g^{2} = x + 3$, dus $x = g^{2} - 3$ en $\mathrm{d}x = 2g\,\mathrm{d}g$. De grenzen gaan mee: bij $x = 1$ hoort $g = \sqrt{4} = 2$ en bij $x = 6$ hoort $g = \sqrt{9} = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 3} = g$: $\displaystyle\int_{1}^{6} x\sqrt{x + 3}\,\mathrm{d}x$$ksql$, 2, $ksql$Zet alles om: $\displaystyle\int_{1}^{6} x\sqrt{x + 3}\,\mathrm{d}x = \int_{2}^{3} \left(g^{2} - 3\right) \cdot g \cdot 2g\,\mathrm{d}g = \int_{2}^{3} \left(2g^{4} - 6g^{2}\right)\mathrm{d}g$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 3} = g$: $\displaystyle\int_{1}^{6} x\sqrt{x + 3}\,\mathrm{d}x$$ksql$, 3, $ksql$Primitiveer en vul de grenzen in: $\left[\tfrac{2}{5}g^{5} - 2g^{3}\right]_{2}^{3} = \left(\tfrac{486}{5} - 54\right) - \left(\tfrac{64}{5} - 16\right) = \tfrac{422}{5} - 38 = \tfrac{232}{5}$. De uitkomst is $46\tfrac{2}{5}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x - 1} = g$: $\displaystyle\int_{1}^{10} x\sqrt{x - 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus (of min) een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt hier niet. Stel daarom de hele wortel gelijk aan een nieuwe variabele $g$. Hier staat een min onder de wortel: $g = \sqrt{x - 1}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x - 1} = g$: $\displaystyle\int_{1}^{10} x\sqrt{x - 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadrateren geeft $g^{2} = x - 1$, dus nu $x = g^{2} + 1$ — let op het plusteken — en $\mathrm{d}x = 2g\,\mathrm{d}g$. De grenzen: bij $x = 1$ hoort $g = 0$ en bij $x = 10$ hoort $g = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x - 1} = g$: $\displaystyle\int_{1}^{10} x\sqrt{x - 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Zet alles om: $\displaystyle\int_{1}^{10} x\sqrt{x - 1}\,\mathrm{d}x = \int_{0}^{3} \left(g^{2} + 1\right) \cdot g \cdot 2g\,\mathrm{d}g = \int_{0}^{3} \left(2g^{4} + 2g^{2}\right)\mathrm{d}g$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x - 1} = g$: $\displaystyle\int_{1}^{10} x\sqrt{x - 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Primitiveer en vul de grenzen in: $\left[\tfrac{2}{5}g^{5} + \tfrac{2}{3}g^{3}\right]_{0}^{3} = \tfrac{486}{5} + 18 - 0 = \tfrac{576}{5}$. De uitkomst is $115\tfrac{1}{5}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{5} \dfrac{6x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus (of min) een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt hier niet. Stel daarom de hele wortel gelijk aan een nieuwe variabele $g$. Hier is dat $g = \sqrt{x + 4}$; de factor $6$ zet je gewoon vóór de integraal.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{5} \dfrac{6x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadrateren geeft $g^{2} = x + 4$, dus $x = g^{2} - 4$ en $\mathrm{d}x = 2g\,\mathrm{d}g$. De grenzen: bij $x = 0$ hoort $g = 2$ en bij $x = 5$ hoort $g = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{5} \dfrac{6x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 2, $ksql$Zet alles om: $\displaystyle\int_{0}^{5} \dfrac{6x}{\sqrt{x + 4}}\,\mathrm{d}x = \int_{2}^{3} \dfrac{6\left(g^{2} - 4\right)}{g} \cdot 2g\,\mathrm{d}g = \int_{2}^{3} \left(12g^{2} - 48\right)\mathrm{d}g$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 4} = g$: $\displaystyle\int_{0}^{5} \dfrac{6x}{\sqrt{x + 4}}\,\mathrm{d}x$$ksql$, 3, $ksql$Primitiveer en vul de grenzen in: $\left[4g^{3} - 48g\right]_{2}^{3} = (108 - 144) - (32 - 96) = -36 + 64 = 28$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 1} = g$: $\displaystyle\int_{0}^{4} \dfrac{x}{\sqrt{2x + 1}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus (of min) een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt hier niet. Stel daarom de hele wortel gelijk aan een nieuwe variabele $g$. Nu staat er $2x$ onder de wortel: $g = \sqrt{2x + 1}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 1} = g$: $\displaystyle\int_{0}^{4} \dfrac{x}{\sqrt{2x + 1}}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadrateren geeft $g^{2} = 2x + 1$, dus $x = \tfrac{1}{2}\left(g^{2} - 1\right)$ en $\mathrm{d}x = \mathrm{d}\left(\tfrac{1}{2}g^{2} - \tfrac{1}{2}\right) = g\,\mathrm{d}g$ — door die $2$ valt de factor $2$ hier weg. De grenzen: bij $x = 0$ hoort $g = 1$ en bij $x = 4$ hoort $g = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 1} = g$: $\displaystyle\int_{0}^{4} \dfrac{x}{\sqrt{2x + 1}}\,\mathrm{d}x$$ksql$, 2, $ksql$Zet alles om: $\displaystyle\int_{0}^{4} \dfrac{x}{\sqrt{2x + 1}}\,\mathrm{d}x = \int_{1}^{3} \dfrac{\tfrac{1}{2}\left(g^{2} - 1\right)}{g} \cdot g\,\mathrm{d}g = \int_{1}^{3} \tfrac{1}{2}\left(g^{2} - 1\right)\mathrm{d}g$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 1} = g$: $\displaystyle\int_{0}^{4} \dfrac{x}{\sqrt{2x + 1}}\,\mathrm{d}x$$ksql$, 3, $ksql$Primitiveer en vul de grenzen in: $\left[\tfrac{1}{6}g^{3} - \tfrac{1}{2}g\right]_{1}^{3} = \left(\tfrac{27}{6} - \tfrac{3}{2}\right) - \left(\tfrac{1}{6} - \tfrac{1}{2}\right) = 3 + \tfrac{1}{3} = \tfrac{10}{3}$. De uitkomst is $3\tfrac{1}{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 3} = g$: $\displaystyle\int_{-1}^{3} x\sqrt{2x + 3}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus (of min) een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt hier niet. Stel daarom de hele wortel gelijk aan een nieuwe variabele $g$. Hier is dat $g = \sqrt{2x + 3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 3} = g$: $\displaystyle\int_{-1}^{3} x\sqrt{2x + 3}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadrateren geeft $g^{2} = 2x + 3$, dus $x = \tfrac{1}{2}\left(g^{2} - 3\right)$ en $\mathrm{d}x = g\,\mathrm{d}g$. De grenzen: bij $x = -1$ hoort $g = \sqrt{1} = 1$ en bij $x = 3$ hoort $g = \sqrt{9} = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 3} = g$: $\displaystyle\int_{-1}^{3} x\sqrt{2x + 3}\,\mathrm{d}x$$ksql$, 2, $ksql$Zet alles om: $\displaystyle\int_{-1}^{3} x\sqrt{2x + 3}\,\mathrm{d}x = \int_{1}^{3} \tfrac{1}{2}\left(g^{2} - 3\right) \cdot g \cdot g\,\mathrm{d}g = \int_{1}^{3} \left(\tfrac{1}{2}g^{4} - \tfrac{3}{2}g^{2}\right)\mathrm{d}g$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{2x + 3} = g$: $\displaystyle\int_{-1}^{3} x\sqrt{2x + 3}\,\mathrm{d}x$$ksql$, 3, $ksql$Primitiveer en vul de grenzen in: $\left[\tfrac{1}{10}g^{5} - \tfrac{1}{2}g^{3}\right]_{1}^{3} = \left(\tfrac{243}{10} - \tfrac{27}{2}\right) - \left(\tfrac{1}{10} - \tfrac{1}{2}\right) = \tfrac{54}{5} + \tfrac{2}{5} = \tfrac{56}{5}$. De uitkomst is $11\tfrac{1}{5}$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}^{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. De grafiek snijdt de $x$-as waar $\ln(x) = 0$, dus bij $x = 1$; tussen $1$ en $\mathrm{e}^{2}$ ligt hij erboven. De oppervlakte is $\displaystyle\int_{1}^{\mathrm{e}^{2}} \dfrac{\ln(x)}{x}\,\mathrm{d}x$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}^{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: welke standaardvorm is dit? Schrijf $\dfrac{\ln(x)}{x} = \ln(x) \cdot \dfrac{1}{x}$: de kern $g(x) = \ln(x)$ met zijn afgeleide $g'(x) = \dfrac{1}{x}$ ernaast → substitutiemethode.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}^{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Primitiveer: $\int g\,\mathrm{d}g = \tfrac{1}{2}g^{2}$, dus $F(x) = \tfrac{1}{2}\ln^{2}(x)$. De grenzen van $g$: bij $x = 1$ hoort $g = 0$, bij $x = \mathrm{e}^{2}$ hoort $g = 2$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}^{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[\tfrac{1}{2}g^{2}\right]_{0}^{2} = \tfrac{1}{2} \cdot 4 - 0 = 2$. De oppervlakte is $2$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sin(x)\cos^{2}(x)$, de $x$-as en de lijn $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. De grafiek snijdt de $x$-as bij $x = 0$ (want $\sin(0) = 0$) en ligt tussen $0$ en $\tfrac{1}{2}\pi$ erboven. De oppervlakte is $\displaystyle\int_{0}^{\frac{1}{2}\pi} \sin(x)\cos^{2}(x)\,\mathrm{d}x$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sin(x)\cos^{2}(x)$, de $x$-as en de lijn $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een macht van de cosinus met een losse sinus ernaast → substitutiemethode met de kern $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$ en $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sin(x)\cos^{2}(x)$, de $x$-as en de lijn $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Primitiveer: $\int -g^{2}\,\mathrm{d}g = -\tfrac{1}{3}g^{3}$, dus $F(x) = -\tfrac{1}{3}\cos^{3}(x)$. De grenzen van $g$: bij $x = 0$ hoort $g = 1$, bij $x = \tfrac{1}{2}\pi$ hoort $g = 0$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sin(x)\cos^{2}(x)$, de $x$-as en de lijn $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[-\tfrac{1}{3}g^{3}\right]_{1}^{0} = 0 - \left(-\tfrac{1}{3}\right) = \tfrac{1}{3}$. De oppervlakte is $\tfrac{1}{3}$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \tan(x)$, de $x$-as en de lijn $x = \tfrac{1}{3}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. De grafiek van $\tan$ snijdt de $x$-as bij $x = 0$ en ligt tussen $0$ en $\tfrac{1}{3}\pi$ erboven. De oppervlakte is $\displaystyle\int_{0}^{\frac{1}{3}\pi} \tan(x)\,\mathrm{d}x$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \tan(x)$, de $x$-as en de lijn $x = \tfrac{1}{3}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: schrijf $\tan(x) = \dfrac{\sin(x)}{\cos(x)}$. De kern is $g(x) = \cos(x)$ met $g'(x) = -\sin(x)$, dus $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$ → substitutiemethode.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \tan(x)$, de $x$-as en de lijn $x = \tfrac{1}{3}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Primitiveer: $\int -\dfrac{1}{g}\,\mathrm{d}g = -\ln|g|$, dus $F(x) = -\ln|\cos(x)|$. Op $\left[0, \tfrac{1}{3}\pi\right]$ is $\cos(x)$ positief, dus de strepen mogen weg.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \tan(x)$, de $x$-as en de lijn $x = \tfrac{1}{3}\pi$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[-\ln(\cos(x))\right]_{0}^{\frac{1}{3}\pi} = -\ln\left(\tfrac{1}{2}\right) + \ln(1) = \ln(2)$. De oppervlakte is $\ln(2)$; exact laten staan.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{3x^{2}}{x^{3} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(9)$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de oppervlakte is $\displaystyle\int_{0}^{p} \dfrac{3x^{2}}{x^{3} + 1}\,\mathrm{d}x$, en die moet $\ln(9)$ worden.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{3x^{2}}{x^{3} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(9)$. Bereken exact $p$.$ksql$, 1, $ksql$Deel 2: een breuk met de kern $g(x) = x^{3} + 1$ in de noemer en teller $g'(x) = 3x^{2}$ → substitutiemethode, met $\ln$ als uitkomst.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{3x^{2}}{x^{3} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(9)$. Bereken exact $p$.$ksql$, 2, $ksql$Primitiveer: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$, dus $F(x) = \ln\left(x^{3} + 1\right)$; voor $x > 0$ is die kern positief. Invullen: $\left[\ln\left(x^{3} + 1\right)\right]_{0}^{p} = \ln\left(p^{3} + 1\right) - \ln(1) = \ln\left(p^{3} + 1\right)$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{3x^{2}}{x^{3} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(9)$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: los de vergelijking op. Uit $\ln\left(p^{3} + 1\right) = \ln(9)$ volgt $p^{3} + 1 = 9$, dus $p^{3} = 8$ en $p = 2$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Gegeven zijn de functies $f(x) = \dfrac{9\ln^{2}(x)}{x}$ en $h(x) = \dfrac{1}{x}$. Bereken exact de oppervlakte van het vlakdeel $V$ dat wordt ingesloten door de grafieken van $f$ en $h$.$ksql$, 0, $ksql$Deel 1 van de driedeling: zoek eerst de snijpunten. Beide functies bestaan alleen voor $x > 0$, dus je mag met $x$ vermenigvuldigen: $9\ln^{2}(x) = 1$ geeft $\ln(x) = \pm\tfrac{1}{3}$, dus $x = \mathrm{e}^{-\frac{1}{3}}$ en $x = \mathrm{e}^{\frac{1}{3}}$. Daartussen ligt $h$ boven $f$, dus de oppervlakte is $\displaystyle\int_{\mathrm{e}^{-1/3}}^{\mathrm{e}^{1/3}} \left(\dfrac{1}{x} - \dfrac{9\ln^{2}(x)}{x}\right)\mathrm{d}x$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Gegeven zijn de functies $f(x) = \dfrac{9\ln^{2}(x)}{x}$ en $h(x) = \dfrac{1}{x}$. Bereken exact de oppervlakte van het vlakdeel $V$ dat wordt ingesloten door de grafieken van $f$ en $h$.$ksql$, 1, $ksql$Deel 2: haal $\dfrac{1}{x}$ voorop: $\left(1 - 9\ln^{2}(x)\right) \cdot \dfrac{1}{x}$. De kern is $g(x) = \ln(x)$ met $g'(x) = \dfrac{1}{x}$ → substitutiemethode.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Gegeven zijn de functies $f(x) = \dfrac{9\ln^{2}(x)}{x}$ en $h(x) = \dfrac{1}{x}$. Bereken exact de oppervlakte van het vlakdeel $V$ dat wordt ingesloten door de grafieken van $f$ en $h$.$ksql$, 2, $ksql$Primitiveer: $\int \left(1 - 9g^{2}\right)\mathrm{d}g = g - 3g^{3}$. De grenzen van $g$: bij $x = \mathrm{e}^{-\frac{1}{3}}$ hoort $g = -\tfrac{1}{3}$, bij $x = \mathrm{e}^{\frac{1}{3}}$ hoort $g = \tfrac{1}{3}$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Gegeven zijn de functies $f(x) = \dfrac{9\ln^{2}(x)}{x}$ en $h(x) = \dfrac{1}{x}$. Bereken exact de oppervlakte van het vlakdeel $V$ dat wordt ingesloten door de grafieken van $f$ en $h$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[g - 3g^{3}\right]_{-\frac{1}{3}}^{\frac{1}{3}} = \left(\tfrac{1}{3} - \tfrac{1}{9}\right) - \left(-\tfrac{1}{3} + \tfrac{1}{9}\right) = \tfrac{2}{9} + \tfrac{2}{9} = \tfrac{4}{9}$. De oppervlakte is $\tfrac{4}{9}$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(3)$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de oppervlakte is $\displaystyle\int_{0}^{p} \dfrac{x}{x^{2} + 1}\,\mathrm{d}x$, en die moet $\ln(3)$ worden.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(3)$. Bereken exact $p$.$ksql$, 1, $ksql$Deel 2: een breuk met de kern $g(x) = x^{2} + 1$ in de noemer. Nu is $g'(x) = 2x$ en staat er maar $x$ in de teller, dus $x\,\mathrm{d}x = \tfrac{1}{2}\,\mathrm{d}\left(x^{2} + 1\right)$ → substitutiemethode, met een halve erbij.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(3)$. Bereken exact $p$.$ksql$, 2, $ksql$Primitiveer: $\int \tfrac{1}{2} \cdot \dfrac{1}{g}\,\mathrm{d}g = \tfrac{1}{2}\ln|g|$, dus $F(x) = \tfrac{1}{2}\ln\left(x^{2} + 1\right)$. Invullen: $\left[\tfrac{1}{2}\ln\left(x^{2} + 1\right)\right]_{0}^{p} = \tfrac{1}{2}\ln\left(p^{2} + 1\right)$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(3)$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: los de vergelijking op. Uit $\tfrac{1}{2}\ln\left(p^{2} + 1\right) = \ln(3)$ volgt $\ln\left(p^{2} + 1\right) = 2\ln(3) = \ln(9)$, dus $p^{2} + 1 = 9$ en $p^{2} = 8$. Omdat $p > 0$: $p = \sqrt{8} = 2\sqrt{2}$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1b_tangens' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1b_gonio' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1b_tangens hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1b_oneven_macht' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1b_gonio' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1b_oneven_macht hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1b_grenzen_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1b_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1b_grenzen_gonio hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1b_grenzen_ln_e' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1b_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1b_grenzen_ln_e hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1b_wortelsubstitutie' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1b_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1b_wortelsubstitutie hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1b_opp_p' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1b_toepassingen' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1b_opp_p hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k1b_gonio', 'k1b_bepaald', 'k1b_toepassingen');
  IF n <> 144 THEN RAISE EXCEPTION 'Deze topics horen samen 144 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
